//! Cargo-driven `shell32.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is shell32-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x7a3a0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ffa4000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ffa4000000u64)),
        o => panic!("shell32-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "engine:uuid", "engine:c:cpprt", "engine:oldnames", "body", "engine:menuband_rust", "engine:recyclebin_rust", "import:powrprof", "import:shdocvw", "import:devmgr", "import:winspool", "import:winmm", "import:mpr", "import:uxtheme", "import:ole32", "import:oleaut32", "import:userenv", "import:browseui", "import:version", "import:fmifs", "import:netapi32", "import:secur32", "import:advapi32", "import:gdi32", "import:user32", "import:comctl32", "import:comdlg32", "import:shlwapi", "import:msvcrt", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "import:kernel32_vista", "engine:pseh", "engine:chkstk", "engine:delayimp_rust"],
        "x86_64" => &["engine:wine", "engine:uuid", "engine:c:cpprt", "engine:oldnames", "body", "engine:menuband_rust", "engine:recyclebin_rust", "import:powrprof", "import:shdocvw", "import:devmgr", "import:winspool", "import:winmm", "import:mpr", "import:uxtheme", "import:ole32", "import:oleaut32", "import:userenv", "import:browseui", "import:version", "import:fmifs", "import:netapi32", "import:secur32", "import:advapi32", "import:gdi32", "import:user32", "import:comctl32", "import:comdlg32", "import:shlwapi", "import:msvcrt", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "import:kernel32_vista", "engine:pseh", "engine:delayimp_rust"],
        "aarch64" => &["engine:wine", "engine:uuid", "engine:c:cpprt", "engine:oldnames", "body", "engine:menuband_rust", "engine:recyclebin_rust", "import:powrprof", "import:shdocvw", "import:devmgr", "import:winspool", "import:winmm", "import:mpr", "import:uxtheme", "import:ole32", "import:oleaut32", "import:userenv", "import:browseui", "import:version", "import:fmifs", "import:netapi32", "import:secur32", "import:advapi32", "import:gdi32", "import:user32", "import:comctl32", "import:comdlg32", "import:shlwapi", "import:msvcrt", "import:kernel32", "import:ntdll", "toolchain:libc++.a", "toolchain:libc++abi.a", "toolchain:libunwind.a", "toolchain:libwinpthread.a", "engine:c:stdc++compat", "import:kernel32_vista", "engine:pseh", "engine:chkstk", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/shell32",
        "dll/win32/shell32",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "UNICODE",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DEBUG=1",
        "_DLL",
        "_SHELL32_",
        "_UNICODE",
        "_WIN32_WINNT=0x600",
        "_WINE",
        "__USE_CRTIMP",
    ];

    Linker::new(target_json)
        .rust_staticlib("shell32-rust")
        .rc("dll/win32/shell32/shell32.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/shell32/shell32.spec", "shell32.dll")
        .spec_stubs()
        .delay_import_lib("dll/win32/powrprof/powrprof.spec", "powrprof.dll", "powrprof")
        .delay_import_lib("dll/win32/shdocvw/shdocvw.spec", "shdocvw.dll", "shdocvw")
        .delay_import_lib("dll/win32/devmgr/devmgr.spec", "devmgr.dll", "devmgr")
        .delay_import_lib("win32ss/printing/base/winspool/winspool.spec", "winspool.drv", "winspool")
        .delay_import_lib("dll/win32/winmm/winmm.spec", "winmm.dll", "winmm")
        .delay_import_lib("dll/win32/mpr/mpr.spec", "mpr.dll", "mpr")
        .delay_import_lib("dll/win32/uxtheme/uxtheme.spec", "uxtheme.dll", "uxtheme")
        .delay_import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .delay_import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .delay_import_lib("dll/win32/userenv/userenv.spec", "userenv.dll", "userenv")
        .delay_import_lib("dll/win32/browseui/browseui.spec", "browseui.dll", "browseui")
        .delay_import_lib("dll/win32/version/version.spec", "version.dll", "version")
        .delay_import_lib("dll/win32/fmifs/fmifs.spec", "fmifs.dll", "fmifs")
        .delay_import_lib("dll/win32/netapi32/netapi32.spec", "netapi32.dll", "netapi32")
        .delay_import_lib("dll/win32/secur32/secur32.spec", "secur32.dll", "secur32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .import_lib("dll/win32/comdlg32/comdlg32.spec", "comdlg32.dll", "comdlg32")
        .import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
